type ButtonAsLink = {
  href: string;
  target?: '_blank' | '_self';
  rel?: string;
} & Omit<React.AnchorHTMLAttributes<HTMLAnchorElement>, 'href'>;

type ButtonAsButton = {
  type?: 'button' | 'submit' | 'reset';
  disabled?: boolean;
} & Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'type'>;

type ButtonProps = {
  variant?: 'primary' | 'secondary';
  size?: 'sm' | 'md' | 'lg';
  children: React.ReactNode;
} & (ButtonAsLink | ButtonAsButton);

function Button(props: ButtonProps) {
  const { variant = 'primary', size = 'md', children, ...rest } = props;

  const className = cn(
    'btn',
    `btn-${variant}`,
    `btn-${size}`
  );

  if ('href' in rest) {
    const { href, target, rel, ...anchorRest } = rest as ButtonAsLink;
    return (
      <a
        href={href}
        target={target}
        rel={rel || (target === '_blank' ? 'noopener noreferrer' : undefined)}
        className={className}
        {...anchorRest}
      >
        {children}
      </a>
    );
  }

  const { type = 'button', disabled, ...buttonRest } = rest as ButtonAsButton;
  return (
    <button
      type={type}
      disabled={disabled}
      className={className}
      {...buttonRest}
    >
      {children}
    </button>
  );
}

// TypeScript knows exactly which props are valid in each branch
<Button href="/home" variant="secondary">Home</Button>
<Button variant="primary" onClick={handleClick} disabled={isDisabled}>
  Submit
</Button>

type BadgeVariants = {
  intent?: 'neutral' | 'success' | 'warning' | 'danger';
  size?: 'sm' | 'md';
  shape?: 'rounded' | 'pill';
};

const defaultVariants: BadgeVariants = {
  intent: 'neutral',
  size: 'md',
  shape: 'rounded',
};

function Badge({
  children,
  intent,
  size,
  shape,
  className,
}: BadgeVariants & { children: React.ReactNode; className?: string }) {
  const classes = cn(
    'badge',
    `badge-${intent || defaultVariants.intent}`,
    `badge-${size || defaultVariants.size}`,
    `badge-${shape || defaultVariants.shape}`,
    className
  );

  return <span className={classes}>{children}</span>;
}

// Usage with defaults
<Badge>Default neutral</Badge>
<Badge intent="success" size="sm">Verified</Badge>
<Badge intent="danger" shape="pill">Error</Badge>

type ListProps = {
  variant?: 'divided' | 'bordered' | 'plain';
  children?: React.ReactNode;
};

function List({ variant = 'plain', children }: ListProps) {
  const context = React.useMemo(() => ({ variant }), [variant]);
  return (
    <ListContext.Provider value={context}>
      <ul className={cn('list', `list-${variant}`)}>{children}</ul>
    </ListContext.Provider>
  );
}

List.Item = function ListItem({ children, className }: { children: React.ReactNode; className?: string }) {
  const { variant } = React.useContext(ListContext);
  return (
    <li className={cn('list-item', `list-item-${variant}`, className)}>
      {children}
    </li>
  );
};

List.Header = function ListHeader({ children, className }: { children: React.ReactNode; className?: string }) {
  return (
    <li className={cn('list-header', className)}>
      {children}
    </li>
  );
};

// Simple variant usage
<List variant="divided">
  <List.Item>First</List.Item>
  <List.Item>Second</List.Item>
</List>

// Compound composition usage
<List>
  <List.Header>Custom Header</List.Header>
  <List.Item className="highlight">Highlighted</List.Item>
  <List.Item>Normal</List.Item>
</List>
